    if(IVD_RES_CHANGED == (dec_op.u4_error_code & 0xFF)){
      ivd_ctl_reset_ip_t ri; ivd_ctl_reset_op_t ro; memset(&ri,0,sizeof ri); memset(&ro,0,sizeof ro);
